describe('batch4 fallback: OUT_OF_SCOPE never selects a TSA event', () => {
    const cases = FALLBACK_CASES.filter((c) => c.c.startsWith('OUT_OF_SCOPE') || c.c === 'NEGATIVE_EVENT_CORPUS');
    it.each(cases)('"%s" is not routed to a specific event', ({ t }) => {
        const { res, resolver } = classify(t);
        expect(EVENT_RESOLVERS.has(resolver), `"${t}" resolved via "${resolver}": "${res.text}"`).toBe(false);
    });
});

describe('batch4 fallback: PERSONAL_ASSISTANT questions get a natural assistant reply', () => {
    const cases = FALLBACK_CASES.filter((c) => c.c === 'PERSONAL_ASSISTANT');
    it.each(cases)('"%s" is answered as a personal/identity question, not an event ask', ({ t }) => {
        const { res, resolver } = classify(t);
        expect(resolver.startsWith('smalltalk:'), `"${t}" resolved via "${resolver}": "${res.text}"`).toBe(true);
        expect(EVENT_RESOLVERS.has(resolver)).toBe(false);
    });
});

describe('batch4 fallback: CAPABILITY_LIMIT is understood, not treated as unknown', () => {
    const cases = FALLBACK_CASES.filter((c) => c.c === 'CAPABILITY_LIMIT');
    it.each(cases)('"%s" is recognized as a capability-limit ask', ({ t }) => {
        const { res } = classify(t);
        expect(res.kind).not.toBe('unknown');
    });
});

